            TtfFont font,
            uint ch,
            out int minx,
            out int maxx,
            out int miny,
            out int maxy,
            out int advance
        )
        {
            minx = default;
            maxx = default;
            miny = default;
            maxy = default;
            advance = default;
            fixed (int* minxPtr = &minx)
            {
                fixed (int* maxxPtr = &maxx)
                {
                    fixed (int* minyPtr = &miny)
                    {
                        fixed (int* maxyPtr = &maxy)
                        {
                            fixed (int* advancePtr = &advance)
                            {
                                return PInvoke.GetGlyphMetrics(font, ch, minxPtr, maxxPtr, minyPtr, maxyPtr, advancePtr)
                                    != 0;
                            }
                        }
                    }
                }
            }
        }

