        ///     <c>offset</c> is greater than or equal to the length of the text string, this
        ///     will return a zero length substring at the end of the text with the
        ///     TTF_SUBSTRING_TEXT_END flag set.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
