        /// <summary>
        ///   Ergonomic wrapper over <c>TTF_GetTextSubStringsForRange</c>.
        /// </summary>
        /// <param name="text">the TTF_Text to query.</param>
        /// <param name="offset">a byte offset into the text string.</param>
        /// <param name="length">
        ///   the length of the range being queried, in bytes, or -1 for
        ///   the remainder of the string.
        /// </param>
        /// <exception cref="SdlException">The SDL call failed; the message carries the <c>SDL_GetError</c>
        ///   text.</exception>
        /// <remarks>
        ///   SDL returns a freshly <c>SDL_malloc</c>'d buffer for this call; the returned array is a managed copy, and
        ///   the native buffer is freed with <c>SDL_free</c> before this method returns.
        /// </remarks>
        public static TtfSubString[] GetTextSubStringsForRange(TtfText* text, int offset, int length)
        {
            int count;
            var ptr = PInvoke.GetTextSubStringsForRange(text, offset, length, &count);
            if (ptr is null)
                throw SdlException.FromError("TTF_GetTextSubStringsForRange failed");
            try
            {
                var result = new TtfSubString[count];
                for (var i = 0; i < count; i++)
                    result[i] = *ptr[i];
                return result;
            }
            finally
            {
                Sdl.PInvoke.Free(ptr);
            }
        }

